import Scholarship from "./components/scholarship";
import JeeApp from "./jee/JeeApp";
import JeeMain from "./components/result/JeeMain";

function App() {
  return (
    <div className="App">
      <BrowserRouter>
        <NavBar />
        <Routes>
          <Route exact path="/" element={<Home />} />
          <Route exact path="/foundation" element={<Foundation />} />
          <Route exact path="/Scholarship" element={<Scholarship />} />
          <Route exact path="/jee" element={<JeeApp />} />
          <Route exact path="/jeeMain" element={<Result />} />
        </Routes>
      </BrowserRouter>
    </div>
  );
}

export default App;
